<template>
  <v-container grid-list-xs fluid>
    <v-overlay :value="overlay">
      <v-progress-circular
        color="primary"
        indeterminate
        size="50"
      ></v-progress-circular>
    </v-overlay>

    <!-- Page Header -->
    <v-row>
      <v-col cols="12">
        <v-card class="mx-auto" outlined>
          <v-card-title
            class="primary darken-1 white--text text-uppercase font-weight-bold"
          >
            <v-icon left color="white">mdi-clipboard-check-multiple</v-icon>
            My Tasks
          </v-card-title>
          <v-card-text class="my-3">
            <v-row align="center">
              <v-col cols="12" md="8">
                <p class="subtitle-1 mb-0">
                  View and manage all tasks assigned to you
                </p>
              </v-col>
              <v-col cols="12" md="4" class="text-right">
                <v-chip class="mr-2" color="orange" text-color="white">
                  <v-icon small left>mdi-clock-outline</v-icon>
                  {{ totalPending }} Pending
                </v-chip>
                <v-chip color="green" text-color="white">
                  <v-icon small left>mdi-check-circle</v-icon>
                  {{ totalDone }} Done
                </v-chip>
              </v-col>
            </v-row>
          </v-card-text>
        </v-card>
      </v-col>
    </v-row>

    <!-- Filter and Search Section -->
    <v-row class="mt-4">
      <v-col cols="12">
        <v-card outlined>
          <v-card-text>
            <v-row>
              <v-col cols="12" md="3">
                <v-text-field
                  v-model="searchName"
                  label="Search by task name"
                  prepend-inner-icon="mdi-magnify"
                  outlined
                  dense
                  clearable
                  hide-details
