                ></v-text-field>
              </v-col>
              <v-col cols="12" md="3">
                <v-select
                  v-model="categoryFilter"
                  :items="categoryOptions"
                  label="Filter by Category"
                  outlined
                  dense
                  clearable
                  hide-details
                  prepend-inner-icon="mdi-tag"
