                >
                  <v-icon left>mdi-refresh</v-icon>
                  Refresh
                </v-btn>
              </v-col>
            </v-row>
          </v-card-text>
        </v-card>
      </v-col>
    </v-row>

    <!-- Tasks List -->
    <v-row class="mt-4">
      <v-col cols="12">
        <v-card outlined>
          <v-tabs v-model="activeTab" background-color="primary darken-1" dark>
            <v-tab>
              <v-icon left>mdi-clock-outline</v-icon>
              Pending ({{ totalPending }})
            </v-tab>
            <v-tab>
              <v-icon left>mdi-check-circle</v-icon>
              Done ({{ totalDone }})
            </v-tab>
            <v-tab>
              <v-icon left>mdi-view-list</v-icon>
              All Tasks ({{ totalAllTasks }})
            </v-tab>
          </v-tabs>

          <v-tabs-items v-model="activeTab">
            <!-- Pending Tasks Tab -->
            <v-tab-item>
              <v-card flat>
                <v-card-text v-if="loading" class="text-center py-8">
                  <v-progress-circular
                    indeterminate
                    color="primary"
                  ></v-progress-circular>
                  <p class="mt-3">Loading tasks...</p>
                </v-card-text>

                <v-card-text
                  v-else-if="tasks.length === 0"
                  class="text-center py-8"
                >
                  <v-icon size="64" color="grey lighten-1"
                    >mdi-clipboard-check</v-icon
                  >
                  <p class="mt-3 subtitle-1">No pending tasks</p>
                </v-card-text>

                <v-list v-else two-line>
                  <template v-for="(task, index) in tasks">
                    <v-list-item :key="task.id">
                      <v-list-item-avatar
                        :color="getCategoryColor(task.category)"
                      >
                        <v-icon dark>{{
                          getCategoryIcon(task.category)
                        }}</v-icon>
                      </v-list-item-avatar>

                      <v-list-item-content>
                        <v-list-item-title class="font-weight-bold">
                          {{ task.name }}
                        </v-list-item-title>
                        <v-list-item-subtitle>
                          {{ task.description }}
                        </v-list-item-subtitle>
                        <v-list-item-subtitle class="mt-1">
                          <v-chip x-small class="mr-2" color="blue lighten-4">
                            <v-icon x-small left>mdi-calendar</v-icon>
                            {{ formatDate(task.date) }}
                          </v-chip>
                          <v-chip
                            x-small
                            class="mr-2"
                            :color="getCategoryColor(task.category)"
                            text-color="white"
                          >
                            <v-icon x-small left>mdi-tag</v-icon>
                            {{ task.categoryDisplay }}
                          </v-chip>
                          <v-chip
                            x-small
                            :color="getStatusColor(task.status)"
                            text-color="white"
                          >
                            {{ task.statusDisplay }}
