                        </v-list-item-subtitle>
                      </v-list-item-content>

                      <v-list-item-action class="flex-row">
                        <v-btn
                          color="primary"
                          small
                          @click="openTask(task)"
                          class="mr-2"
                        >
                          <v-icon left small>mdi-arrow-right</v-icon>
