                </v-list>

                <!-- Pagination -->
                <v-divider v-if="tasks.length > 0"></v-divider>
                <v-card-actions v-if="tasks.length > 0" class="justify-center">
                  <v-pagination
                    v-model="pendingPage"
                    :length="totalPages"
                    :total-visible="7"
