                  ></v-pagination>
                </v-card-actions>
                <div
                  v-if="tasks.length > 0"
                  class="text-center pb-3 caption grey--text"
                >
                  Showing {{ tasks.length }} of {{ totalTasks }} tasks ({{
                    pageSize
                  }}
                  per page)
                </div>
              </v-card>
            </v-tab-item>

            <!-- Done Tasks Tab -->
            <v-tab-item>
              <v-card flat>
                <v-card-text v-if="loading" class="text-center py-8">
                  <v-progress-circular
                    indeterminate
                    color="primary"
                  ></v-progress-circular>
                  <p class="mt-3">Loading tasks...</p>
                </v-card-text>

                <v-card-text
                  v-else-if="tasks.length === 0"
                  class="text-center py-8"
                >
                  <v-icon size="64" color="grey lighten-1"
                    >mdi-clipboard-check-outline</v-icon
                  >
                  <p class="mt-3 subtitle-1">No completed tasks</p>
                </v-card-text>

                <v-list v-else two-line>
                  <template v-for="(task, index) in tasks">
                    <v-list-item :key="task.id">
                      <v-list-item-avatar
                        :color="getCategoryColor(task.category)"
                      >
                        <v-icon dark>{{
                          getCategoryIcon(task.category)
                        }}</v-icon>
                      </v-list-item-avatar>

                      <v-list-item-content>
                        <v-list-item-title class="font-weight-bold">
                          {{ task.name }}
                        </v-list-item-title>
                        <v-list-item-subtitle>
                          {{ task.description }}
                        </v-list-item-subtitle>
                        <v-list-item-subtitle class="mt-1">
                          <v-chip x-small class="mr-2" color="blue lighten-4">
                            <v-icon x-small left>mdi-calendar</v-icon>
                            {{ formatDate(task.date) }}
                          </v-chip>
                          <v-chip
                            x-small
                            class="mr-2"
                            :color="getCategoryColor(task.category)"
                            text-color="white"
                          >
                            <v-icon x-small left>mdi-tag</v-icon>
                            {{ task.categoryDisplay }}
                          </v-chip>
                          <v-chip
                            x-small
                            :color="getStatusColor(task.status)"
                            text-color="white"
                          >
                            {{ task.statusDisplay }}
                          </v-chip>
                        </v-list-item-subtitle>
                      </v-list-item-content>

                      <v-list-item-action class="flex-row">
                        <v-btn
                          color="grey"
                          outlined
                          small
                          @click="openTask(task)"
                          class="mr-2"
                        >
                          <v-icon left small>mdi-eye</v-icon>
                          View
                        </v-btn>
                        <v-btn
                          color="orange"
                          dark
                          small
                          @click="markTaskStatus(task, 'pending')"
                          :loading="!!markingDone[task.id]"
                          :disabled="!!markingDone[task.id]"
                        >
                          <v-icon left small>mdi-undo</v-icon>
                          Mark Pending
                        </v-btn>
                      </v-list-item-action>
                    </v-list-item>
                    <v-divider
                      v-if="index < tasks.length - 1"
                      :key="'divider-' + index"
                    ></v-divider>
                  </template>
                </v-list>

                <!-- Pagination -->
                <v-divider v-if="tasks.length > 0"></v-divider>
                <v-card-actions v-if="tasks.length > 0" class="justify-center">
                  <v-pagination
                    v-model="donePage"
                    :length="totalPages"
                    :total-visible="7"
                    circle
                  ></v-pagination>
                </v-card-actions>
              </v-card>
            </v-tab-item>

            <!-- All Tasks Tab -->
            <v-tab-item>
              <v-card flat>
                <v-card-text v-if="loading" class="text-center py-8">
                  <v-progress-circular
                    indeterminate
                    color="primary"
                  ></v-progress-circular>
                  <p class="mt-3">Loading tasks...</p>
                </v-card-text>

                <v-card-text
                  v-else-if="tasks.length === 0"
                  class="text-center py-8"
                >
                  <v-icon size="64" color="grey lighten-1"
                    >mdi-clipboard-text-outline</v-icon
                  >
                  <p class="mt-3 subtitle-1">No tasks found</p>
                </v-card-text>

                <div v-else>
                  <v-data-table
                    :headers="tableHeaders"
                    :items="tasks"
                    :items-per-page="pageSize"
                    hide-default-footer
                    class="elevation-0"
                    disable-sort
                  >
                    <template v-slot:item.name="{ item }">
                      <div>
                        <div class="font-weight-bold">{{ item.name }}</div>
                        <div class="text-caption text--secondary">
                          {{ item.description }}
                        </div>
                      </div>
                    </template>

                    <template v-slot:item.category="{ item }">
                      <v-chip
                        small
                        :color="getCategoryColor(item.category)"
                        text-color="white"
                      >
                        <v-icon x-small left>{{
                          getCategoryIcon(item.category)
                        }}</v-icon>
                        {{ item.categoryDisplay }}
                      </v-chip>
                    </template>

                    <template v-slot:item.date="{ item }">
                      <v-chip small color="blue lighten-4">
                        <v-icon x-small left>mdi-calendar</v-icon>
                        {{ formatDate(item.date) }}
                      </v-chip>
                    </template>

                    <template v-slot:item.status="{ item }">
                      <v-chip
                        small
                        :color="getStatusColor(item.status)"
                        text-color="white"
                      >
                        {{ item.statusDisplay }}
                      </v-chip>
                    </template>

                    <template v-slot:item.actions="{ item }">
                      <v-btn
                        small
                        :color="item.status === 'pending' ? 'primary' : 'grey'"
                        :outlined="item.status !== 'pending'"
                        @click="openTask(item)"
                        class="mr-2"
                      >
                        <v-icon left small>
                          {{
                            item.status === "pending"
                              ? "mdi-arrow-right"
                              : "mdi-eye"
                          }}
                        </v-icon>
                        {{ item.status === "pending" ? "Open" : "View" }}
                      </v-btn>
                      <v-btn
                        v-if="item.status === 'pending'"
                        small
                        color="green"
                        dark
                        @click="markTaskStatus(item, 'done')"
                        :loading="!!markingDone[item.id]"
                        :disabled="!!markingDone[item.id]"
                      >
                        <v-icon left small>mdi-check</v-icon>
                        Mark Done
                      </v-btn>
                      <v-btn
                        v-if="item.status === 'done'"
                        small
                        color="orange"
                        dark
                        @click="markTaskStatus(item, 'pending')"
                        :loading="!!markingDone[item.id]"
                        :disabled="!!markingDone[item.id]"
                      >
                        <v-icon left small>mdi-undo</v-icon>
                        Mark Pending
                      </v-btn>
                    </template>
                  </v-data-table>

                  <!-- Manual Pagination -->
                  <v-divider></v-divider>
                  <v-card-actions class="justify-center">
                    <v-pagination
                      v-model="allPage"
                      :length="totalPages"
                      :total-visible="7"
                      circle
                    ></v-pagination>
                  </v-card-actions>
                </div>
              </v-card>
            </v-tab-item>
          </v-tabs-items>
        </v-card>
      </v-col>
    </v-row>
  </v-container>
</template>

<script>
// Vuetify color names cycled through for any task category that isn't
// hand-picked in getCategoryColor() below — keeps a new category visually
// distinct without needing a code change every time one is added.
const FALLBACK_COLORS = [
  "blue-grey",
  "teal darken-1",
  "amber darken-2",
  "light-green darken-1",
  "blue darken-1",
  "orange darken-1",
];

export default {
  name: "MyTasks",
  data() {
    return {
      overlay: false,
      loading: true,
      activeTab: 0,
      searchName: "",
      searchDescription: "",
      searchTimeout: null,
      categoryFilter: null,
      markingDone: {},

      tasks: [],

      // Separate page variable for each tab
      pendingPage: 1,
      donePage: 1,
      allPage: 1,

      pageSize: 5,
      totalTasks: 0,
      totalPending: 0,
      totalDone: 0,
      totalAllTasks: 0,

      // Category options for the filter dropdown — populated dynamically
      // from TaskCategoryCodeSystem (see loadCategoryOptions()) rather than
      // hardcoded, so a new category added to the codesystem shows up here
      // automatically instead of silently being unfilterable.
      categoryOptions: [],

      tableHeaders: [
        { text: "Task", value: "name", width: "35%", sortable: false },
        { text: "Category", value: "category", width: "15%", sortable: false },
        { text: "Date", value: "date", width: "15%", sortable: false },
        { text: "Status", value: "status", width: "15%", sortable: false },
        { text: "Actions", value: "actions", sortable: false, width: "20%" },
      ],
    };
  },

  computed: {
    currentUserId() {
      // Get current user ID from Vuex store
      return this.$store.state.user?.obj?.resource?.id;
    },

    totalPages() {
      let total = 0;

      if (this.activeTab === 0) {
        total = this.totalPending;
      } else if (this.activeTab === 1) {
        total = this.totalDone;
      } else {
        total = this.totalAllTasks;
      }

      return Math.ceil(total / this.pageSize) || 1;
    },

    // Determine which status to filter by based on active tab
    activeStatusFilter() {
      if (this.activeTab === 0) return "pending";
      if (this.activeTab === 1) return "done";
      return null; // All tasks - no status filter
    },

    // Get current page based on active tab
    currentPage() {
      if (this.activeTab === 0) return this.pendingPage;
      if (this.activeTab === 1) return this.donePage;
      return this.allPage;
    },
  },

  watch: {
    // Watch each tab's page separately
    pendingPage() {
      if (this.activeTab === 0) {
        this.loadTasks();
      }
    },

    donePage() {
      if (this.activeTab === 1) {
        this.loadTasks();
      }
    },

    allPage() {
      if (this.activeTab === 2) {
        this.loadTasks();
      }
    },

    // Watch tab changes
    activeTab() {
      this.loadTasks();
    },
  },

  methods: {
    async loadTasks() {
      this.loading = true;
      try {
        if (!this.currentUserId) {
          console.error("User ID not found");
          this.loading = false;
          return;
        }

        // Build query parameters
        const params = new URLSearchParams();

        // Required params
        params.append(
          "_profile",
          "http://ihris.org/fhir/StructureDefinition/user-assigned-tasks-profile",
        );
        params.append("user", `Person/${this.currentUserId}`);

        // Pagination params - use currentPage computed property
        params.append("_count", this.pageSize.toString());
        params.append(
          "_getpagesoffset",
          ((this.currentPage - 1) * this.pageSize).toString(),
        );

        // Sort by date (newest first)
        params.append("_sort", "-_lastUpdated");

        // Status filter ONLY for pending and done tabs
        if (this.activeStatusFilter) {
          params.append("usertaskstatus", this.activeStatusFilter);
        }

        // Name search
        if (this.searchName) {
          params.append("usertaskname:contains", this.searchName);
        }

        // Description search
        if (this.searchDescription) {
          params.append("usertaskdescription:contains", this.searchDescription);
        }

        // Category filter (applies to all tabs)
        if (this.categoryFilter) {
          params.append("usertaskcategory", this.categoryFilter);
        }

        console.log(
          "Loading tasks - Tab:",
          this.activeTab,
          "Page:",
          this.currentPage,
          "Query:",
          params.toString(),
        );

        // Fetch tasks from server
        const response = await fetch(`/fhir/Basic?${params.toString()}`);

        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }

        const results = await response.json();

        console.log(
          "Received results - Total:",
          results.total,
          "Entries:",
          results.entry?.length || 0,
        );

        // Extract total count from bundle
        this.totalTasks = results.total || 0;

        // Parse tasks
        this.tasks = [];

        if (results && results.entry && results.entry.length > 0) {
          for (let entry of results.entry) {
            const resource = entry.resource;

            // Extract task category
            const categoryExt = resource.extension?.find(
              (ext) =>
                ext.url ===
                "http://ihris.org/fhir/StructureDefinition/task-category",
            );

            const category = categoryExt?.valueCoding?.code || "general";
            const categoryDisplay =
              categoryExt?.valueCoding?.display || "General";

            // Extract task description
            const taskDescExt = resource.extension?.find(
              (ext) =>
                ext.url ===
                "http://ihris.org/fhir/StructureDefinition/user-task-description",
            );

            if (taskDescExt && taskDescExt.extension) {
              const nameExt = taskDescExt.extension.find(
                (e) => e.url === "name",
              );
              const descExt = taskDescExt.extension.find(
                (e) => e.url === "description",
              );
              const dateExt = taskDescExt.extension.find(
                (e) => e.url === "date",
              );
              const urlExt = taskDescExt.extension.find((e) => e.url === "url");
              const idExt = taskDescExt.extension.find((e) => e.url === "id");
              const statusExt = taskDescExt.extension.find(
                (e) => e.url === "status",
              );

              this.tasks.push({
                id: resource.id,
                resourceId: idExt?.valueString || "",
                name: nameExt?.valueString || "Untitled Task",
                description: descExt?.valueString || "",
                date:
                  dateExt?.valueDate ||
                  resource.meta?.lastUpdated?.split("T")[0] ||
                  "",
                url: urlExt?.valueString || "",
                status: statusExt?.valueCoding?.code || "pending",
                statusDisplay: statusExt?.valueCoding?.display || "Pending",
                category: category,
                categoryDisplay: categoryDisplay,
              });
            }
          }
        }

        console.log("Parsed tasks:", this.tasks.length);
      } catch (error) {
        console.error("Error loading tasks:", error);
      } finally {
        this.loading = false;
      }
    },

    // Fetches TaskCategoryValueset (expands TaskCategoryCodeSystem in
    // LesothoTerminologies.fsh) so the category filter always reflects
    // whatever categories actually exist, instead of a hardcoded list that
    // silently drifts out of date as new task categories are added.
    async loadCategoryOptions() {
      try {
        const concepts = await this.$fhirutils.expand(
          "http://ihris.org/fhir/ValueSet/task-category-valueset",
        );
        this.categoryOptions = (concepts || []).map((c) => ({
          text: c.display || c.code,
          value: c.code,
        }));
      } catch (error) {
        console.error("Error loading task categories:", error);
      }
    },

    async loadCounts() {
      try {
        // Load pending count
        const pendingParams = new URLSearchParams({
          _profile:
            "http://ihris.org/fhir/StructureDefinition/user-assigned-tasks-profile",
          user: `Person/${this.currentUserId}`,
          usertaskstatus: "pending",
          _summary: "count",
        });

        const pendingResponse = await fetch(
          `/fhir/Basic?${pendingParams.toString()}`,
        );
        const pendingResults = await pendingResponse.json();
        this.totalPending = pendingResults.total || 0;

        // Load done count
        const doneParams = new URLSearchParams({
          _profile:
            "http://ihris.org/fhir/StructureDefinition/user-assigned-tasks-profile",
          user: `Person/${this.currentUserId}`,
          usertaskstatus: "done",
          _summary: "count",
        });

        const doneResponse = await fetch(
          `/fhir/Basic?${doneParams.toString()}`,
        );
        const doneResults = await doneResponse.json();
        this.totalDone = doneResults.total || 0;

        // Load all tasks count (no status filter)
        const allParams = new URLSearchParams({
          _profile:
            "http://ihris.org/fhir/StructureDefinition/user-assigned-tasks-profile",
          user: `Person/${this.currentUserId}`,
          _summary: "count",
        });

        const allResponse = await fetch(`/fhir/Basic?${allParams.toString()}`);
        const allResults = await allResponse.json();
        this.totalAllTasks = allResults.total || 0;
      } catch (error) {
        console.error("Error loading counts:", error);
      }
    },

    applyFilters() {
      // Reset all pages to 1 when applying filters
      this.pendingPage = 1;
      this.donePage = 1;
      this.allPage = 1;
      this.loadTasks();
    },

    debounceSearch() {
      // Clear existing timeout
      if (this.searchTimeout) {
        clearTimeout(this.searchTimeout);
      }

      // Set new timeout
      this.searchTimeout = setTimeout(() => {
        this.applyFilters();
      }, 500);
    },

    refreshTasks() {
      // Reset current tab's page to 1
      if (this.activeTab === 0) this.pendingPage = 1;
      if (this.activeTab === 1) this.donePage = 1;
      if (this.activeTab === 2) this.allPage = 1;

      this.loadCounts(); // Refresh counts
      this.loadTasks();
    },

    async markTaskStatus(task, newStatus) {
      this.$set(this.markingDone, task.id, true);
      try {
        const response = await fetch("/site/general/change-task-status", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ id: task.id, status: newStatus }),
        });
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        await this.loadCounts();
        await this.loadTasks();
      } catch (error) {
        console.error("Error changing task status:", error);
      } finally {
        this.$delete(this.markingDone, task.id);
      }
    },

    openTask(task) {
      if (task.url) {
        this.$router.push(task.url);
      } else {
        console.warn("No URL for task:", task);
      }
    },

    formatDate(dateString) {
      if (!dateString) return "N/A";
      const date = new Date(dateString);
      return date.toLocaleDateString("en-GB", {
        day: "2-digit",
        month: "short",
        year: "numeric",
      });
    },

    getStatusColor(status) {
      const colors = {
        pending: "orange",
        done: "green",
      };
      return colors[status] || "grey";
    },

    getCategoryColor(category) {
      const colors = {
        training: "indigo",
        leave: "teal",
        cancelleave: "deep-orange",
        performanceplan: "purple",
        performancereview: "deep-purple",
        transfers: "cyan darken-1",
        compulsoryretirement: "brown",
        earlyretirementrequest: "pink darken-1",
        general: "blue-grey",
      };
      if (colors[category]) return colors[category];
      // Any category not hand-picked above (e.g. a new one just added to
      // TaskCategoryCodeSystem) still gets a distinct, stable color rather
      // than every unknown category collapsing onto the same grey.
      return FALLBACK_COLORS[this.hashCode(category) % FALLBACK_COLORS.length];
    },

    getCategoryIcon(category) {
      const icons = {
        training: "mdi-school",
        leave: "mdi-calendar-clock",
        cancelleave: "mdi-calendar-remove",
        performanceplan: "mdi-target",
        performancereview: "mdi-chart-line",
        transfers: "mdi-swap-horizontal",
        compulsoryretirement: "mdi-account-clock",
        earlyretirementrequest: "mdi-account-clock-outline",
        general: "mdi-clipboard-text",
      };
      return icons[category] || "mdi-clipboard-text";
    },

    // Small stable string hash — only used to pick a deterministic fallback
    // color index, not for anything security-sensitive.
    hashCode(str) {
      let hash = 0;
      for (let i = 0; i < (str || "").length; i++) {
        hash = (hash << 5) - hash + str.charCodeAt(i);
        hash |= 0;
      }
      return Math.abs(hash);
    },
  },

  async created() {
    await this.loadCategoryOptions();
    await this.loadCounts();
    await this.loadTasks();
  },

  beforeDestroy() {
    // Clear search timeout
    if (this.searchTimeout) {
      clearTimeout(this.searchTimeout);
    }
  },
};
</script>

